from pathlib import Path
import base64,zlib,hashlib
DATA = """[... ELLIPSIZATION ...]"""
out=Path("factory_pc_tool_v041/visionsen_factory_tool.py")
out.parent.mkdir(parents=True, exist_ok=True)
raw=zlib.decompress(base64.b64decode(DATA))
expected="5c79cd04cc6dee8399870ff14b65205528fb1bce164de175d47ed6f88e4cc680"
actual=hashlib.sha256(raw).hexdigest()
if actual != expected:
    raise SystemExit(f"v0.4.1 source hash mismatch: {actual}")
out.write_bytes(raw)
print(f"wrote {out} sha256={actual}")
